async function getCurrentGame(telegramId) {
  const [game] = await pool.execute(
    "SELECT * FROM games WHERE telegram_id = ? and status='active'",
    [telegramId]
  );

  if (game.length > 0) {
    game[0].previous_scenes = JSON.parse(game[0].previous_scenes) || [];
    game[0].last_option = game[0].current_scene % 10;
    const [scenes] = await pool.execute(
    "SELECT * FROM scenes WHERE game_id = ?",
    [game[0].game_id]
    );
    const [scene] = await pool.execute(
			"SELECT * FROM scenes WHERE game_id = ? and scene_id = ?",
			[game[0].game_id, game[0].current_scene]
		);
    return {
			current: game[0],
			scenes: scenes,
			scene: scene[0],
			last_option: game[0].last_option,
		};
  }
  else return false;
}

