async function registerUser(username, telegramId, language="en", first_name="", last_name="") {

  const registrationDate = new Date();

  const sql =
    "INSERT INTO users (username, telegram_id, registration_date, language, first_name, last_name, status) VALUES (?, ?, ?, ?, ?, ?, 'active')";
  const params = [
    username,
    telegramId,
    registrationDate,
    language,
    first_name,
    last_name,
  ];
  await pool.execute(sql, params);
  return { username: username, telegram_id: telegramId, registration_date: registrationDate, language: language };
}

async function createGame(telegram_id, total_steps) {
  const player_hp = parseInt(process.env.PLAYER_HP);
  total_steps = parseInt(total_steps);
  const dice_probabilities = process.env.INITIAL_DICE_PROBABILITIES;
  const seed = parseInt(Math.floor(Math.random() * 2147483646));
  const combat_options = process.env.COMBAT_OPTIONS;
  const base_success = process.env.BASE_SUCCESS;
  const enemy_initial_hp=parseInt(process.env.ENEMY_INITIAL_HP);
  const insertGameSql =
		'INSERT INTO games (telegram_id, total_steps, current_scene, status, step, player_hp, dice_probabilities, combat_options, base_success, enemy_initial_hp, seed) VALUES (?, ?, 100, "active", 1, ?, ?, ?, ?, ?, ?)';
  const [result] = await pool.execute(insertGameSql, [telegram_id, total_steps, player_hp, dice_probabilities, combat_options, base_success, enemy_initial_hp, seed]); 
  if (result.affectedRows === 0) {
    throw new Error('Failed to create game');
  }

  const game_id = result.insertId;

  const updateUserSql = 'UPDATE users SET current_game_id = ? WHERE telegram_id = ?';
  await pool.execute(updateUserSql, [game_id, telegram_id]);

  return { game_id: game_id, total_steps: total_steps, current_scene: 100, step: 1, player_hp: player_hp, dice_probabilities: JSON.parse(dice_probabilities), combat_options: JSON.parse(combat_options), base_success: JSON.parse(base_success), enemy_initial_hp: enemy_initial_hp, status: 'active', seed: seed };
}

