async function finishGame(ctx, status="cancelled") {
    ctx.session.game = null;		

  const updateUserSql = `update users set current_game_id = null where telegram_id = ?`;
  await pool.execute(updateUserSql, [ctx.from.id]);

  const updateGameSql = `update games set status = ? where game_id = ?`;
  await pool.execute(updateGameSql, [status, ctx.session.user.current_game_id]);
  ctx.session.user.current_game_id = null;
}

