async function insertSceneToDB(scene, game_id) {
  const insertSceneSql = `INSERT INTO scenes (
      game_id, scene_id, parent_id, step, description, option_1, option_2, option_3, option_4, option_5,
      img_prompt_1, img_prompt_2, img_prompt, is_combat, is_npc, is_victory, is_defeat, img_id,
      player_hp, enemy_hp, dice_probabilities, result, combat_step, last_action_type,
      base_success, combat_options, enemy_initial_hp,enemy_state, precombat, environment, npc_id, npc_name
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `;

  // Replace undefined values with null
  const params = [
		game_id,
		scene.scene_id || null,
		scene.parent_id || null,
		scene.step || null,
		scene.description || null,
		scene.option_1 || null,
		scene.option_2 || null,
		scene.option_3 || null,
		scene.option_4 || null,
		scene.option_5 || null,
		scene.img_prompt_1 || null,
		scene.img_prompt_2 || null,
		scene.img_prompt || null,
		scene.is_combat || 0,
		scene.is_npc || 0,
		scene.is_victory || 0,
		scene.is_defeat || 0,
		scene.img_id || null,
		scene.player_hp || parseInt(process.env.PLAYER_HP),
		scene.enemy_hp || null,
		scene.dice_probabilities || process.env.INITIAL_DICE_PROBABILITIES,
		scene.result || null,
		scene.combat_step || null,
		scene.last_action_type || null,
		scene.base_success || process.env.BASE_SUCCESS,
		scene.combat_options || process.env.COMBAT_OPTIONS,
		scene.enemy_initial_hp || null,
		scene.enemy_state || null,
		scene.precombat || null,
		scene.environment || null,
		scene.npc_id || null,
		scene.npc_name || null,
	];


  try {
    let [result] = await pool.execute(insertSceneSql, params);
    if (result.insertId) return result.insertId;
		else return false; 
  } catch (error) {
    console.error("Error inserting scene to DB:", error);
    throw error;
  }
}

